grid[24].append(3); grid[25].append(5)
# Restore outer background/frame cells obscured by the mask.
for c in range(11,18): grid[1][c]=1; grid[2][c]=4
for r in range(9,18):
    for c in range(3):
        if grid[r][c]==0: grid[r][c]=1 if c<2 else 4
# Fill masked cells in the patterned field using the horizontal 5-color cycle.
cycle=[3,5,7,9,1]
for r,row in enumerate(grid):
    for c,v in enumerate(row):
        if v==0 and c>=3:
            anchors=[j for j in range(3,28) if row[j] in cycle]
            j=min(anchors,key=lambda j:abs(j-c))
            row[c]=cycle[(cycle.index(row[j])+(c-j))%5]
print([len(r) for r in grid], sum(v==0 for row in grid for v in row))
for i,row in enumerate(grid): print(i+1,' '.join(map(str,row)))
